using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
using Newtonsoft.Json.Linq;
namespace MPNDossier;
public static class DossierHelp
{
 public static readonly JObject Objects=Read("Tooltips_Obj.json"),Enums=Read("Tooltips_Enums.json");
 static JObject Read(string name){using(var stream=typeof(DossierHelp).Assembly.GetManifestResourceStream("Dossier.Help."+name))using(var reader=new StreamReader(stream))return JObject.Parse(reader.ReadToEnd());}
 static readonly Dictionary<string,string> Types=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){
  {"characters","Character"},{"animsets","AnimationProfile"},{"animation","Animations"},{"chatter","Chatter"},{"corpus","Corpus"},{"dot","DoT"},{"loadouts","Loadout"},{"storyloadouts","Loadout"},{"origins","Origin"},{"skillgroups","SkillGroup"},{"wardrobe","Wardrobe"},{"swatches","Swatch"},{"armor","Armor"},{"weapons","Melee"},{"weaponmodded","Ranged"},{"ammo","Ammo"},{"weaponaddons","Addon"},{"thrown","Thrown"},{"ranged","Ranged"},{"weaponaddongroups","AddonGroup"},{"skins","Skin"},{"executions","Execution"},{"explosions","Explosion"},{"stories","Stage_Story"},{"arenas","Stage_Arena"},
  {"UniformList","ArmorList"},{"AnimPair","AnimationPair"},{"CharSet","CharacterSet"},{"Sequence","WaveSequence"},{"Bonus","BonusStat"},{"Buff","BuffEffect"}};
 static readonly Dictionary<string,string> CharacterNames=new Dictionary<string,string>{
  {"FullName","Name"},{"ShortName","NameShort"},{"DefaultFaction","Faction"},{"Speed_SprintBonus","SprintBonus"},{"AlternateParts","AltModels"},{"VariableTint","TintsPrimary"},{"VariableTint2","TintsSecondary"},{"VariableArmor","RandomArmor"},{"WeaponPreference","WeaponPref"},{"ItemGenres","WeaponGenres"},{"DefaultPrimary","DefaultWeapon"},{"DefaultSecondary","DefaultOffHand"},{"Groups","SkillGroups"},{"RemoveSkills","RemovedSkills"},{"FallLand","FallPuff"}};
 public static string ObjectType(string name){string result;return name!=null&&Types.TryGetValue(name,out result)?result:name;}
 static string Normalize(string value)=>new string((value??"").Where(char.IsLetterOrDigit).Select(char.ToLowerInvariant).ToArray());
 static JToken Lookup(JObject obj,string key)=>obj?.Properties().FirstOrDefault(p=>Normalize(p.Name)==Normalize(key))?.Value;
 static JToken Definition(string type,string property)
 {
  type=ObjectType(type);string mapped;
  if(type=="Character"&&CharacterNames.TryGetValue(property,out mapped))property=mapped;
  if(type=="Uniform")property=property=="Tint"?"TintPrimary":property=="Tint2"?"TintSecondary":property=="Glass"?"TintGlass":property=="AltMaterialIndex"?"AltMaterial":property=="AltMeshIndex"?"AltMesh":property;
  return Lookup(Lookup(Objects,type) as JObject,"Properties") is JObject props?Lookup(props,property):null;
 }
 public static string Describe(string type,string property)=>Format(Definition(type,property));
 public static string Format(JToken definition)
 {
  if(definition==null)return "";if(definition.Type!=JTokenType.Object)return definition.ToString();var output=new StringBuilder();
  foreach(var key in new[]{"Description","Definitions","Notes","Warnings"}){
   var value=definition[key];if(value==null)continue;
   if(key!="Description")output.AppendLine().AppendLine(key=="Warnings"?"Watch out":key=="Definitions"?"Values":"Notes");
   if(value is JObject obj){foreach(var p in obj.Properties())output.AppendLine(p.Name+" — "+p.Value);}
   else if(value is JArray array){foreach(var item in array)output.AppendLine("• "+item);}
   else output.AppendLine(value.ToString());
  }
  return output.ToString().Trim();
 }
 public static string FieldText(string folder,TreeNode node)
 {
  var tag=node?.Tag as ModCards.NodeTag;if(tag==null)return "Select a property to read what it does.";
  string type=ObjectType(folder),name=tag.LinkedControl.PropName;
  for(var parent=node.Parent;parent!=null;parent=parent.Parent){var pt=parent.Tag as ModCards.NodeTag;if(pt?.NodeType==ModCards.NodeType.Obj){type=ObjectType(pt.LinkedControl.ObjectName);break;}}
  string explanation=Describe(type,name);
  if(string.IsNullOrWhiteSpace(explanation)&&node.Parent!=null){
   var parentTag=node.Parent.Tag as ModCards.NodeTag;
   if(parentTag!=null&&(parentTag.LinkedControl.ObjectName=="Vec2"||parentTag.LinkedControl.ObjectName=="Vec3"))explanation=Describe(ObjectType(folder),parentTag.LinkedControl.PropName);
  }
  var result=new StringBuilder(name+"\r\n\r\n");
  result.Append(string.IsNullOrWhiteSpace(explanation)?"No MadCard Maker description matches this field in this version of Dossier.":explanation);
  result.AppendLine().AppendLine().Append("Editing: ").Append(tag.NodeType==ModCards.NodeType.Arr?"select the list and use Add item; select a child to edit or remove it.":tag.LinkedControl.PropType==ModCards.PropType.Ref?"choose an existing ID from Available values.":tag.LinkedControl.PropType==ModCards.PropType.Bool?"use Toggle to switch this setting on or off.":tag.LinkedControl.PropType==ModCards.PropType.Obj?"expand this object to edit its individual properties.":tag.LinkedControl.PropType==ModCards.PropType.Int?"enter a whole number. Invalid text keeps the previous value.":tag.LinkedControl.PropType==ModCards.PropType.Float?"enter a decimal number. Invalid text keeps the previous value.":tag.LinkedControl.PropType==ModCards.PropType.Color?"enter a color or use Choose color.":"edit the value below.");
  var value=tag.Value as Enum;
  if(value!=null){string enumName=value.GetType().Name;var group=Enums.Properties().FirstOrDefault(p=>Normalize(p.Name)==Normalize(enumName)||Normalize(p.Name)==Normalize(enumName)+"s");var detail=Format((group?.Value as JObject)?[value.ToString()]);if(detail.Length>0)result.AppendLine().AppendLine().AppendLine(value.ToString()).Append(detail);}
  if(!string.IsNullOrWhiteSpace(explanation))result.AppendLine().AppendLine().Append("Reference: MadCard Maker. Names are mapped to Dossier's schema; behavior may vary by game version.");
  return result.ToString();
 }
 public static Dictionary<string,string> Articles()
 {
  var items=new Dictionary<string,string>{
   {"Files and custom windows","Files opens the self-contained red-and-black explorer from the main window or editor menu. Open, Save, Save as, folder selection, and Theme Editor import/export use the same browser. Project/deck folder buttons also stay inside REVANCED.\r\n\r\nBack, Forward and Up navigate folders. Type a location in the address bar (Ctrl+L), search filenames (Ctrl+F), or use drives, common folders and recent locations in the sidebar. F5 refreshes; Alt+Left goes back. Double-click or Enter opens a folder or selects a file.\r\n\r\nPreview small text/JSON and supported images. Edit entry opens typed JSON in the workbench or Rooms. Types are inferred from known ancestor folders; choose an entry type beside Refresh for a JSON elsewhere. Project manifests open Project Manager.\r\n\r\nSave checks filenames, adds the chosen extension and asks before replacing a file. Folder mode selects the current or highlighted folder. Folder name plus New folder creates a directory. Missing/inaccessible locations show an inline explanation without discarding the current location. Listings are limited to 5,000 immediate items; text previews to 512 KB and image previews to 10 MB.\r\n\r\nCustom flat frames suppress Windows non-client border painting, with rounded corners. Title bars support dragging, minimize/maximize and edge resizing. Windows fade in, buttons animate hover/press states and tab indicators slide between selections. Smooth interface animations can be disabled in audio/interface settings. Close still honors unsaved-change prompts. Custom confirmations are silent and cancel safely when closed. Common text-field Windows dings are suppressed. Quiet click and typing feedback is enabled on the first launch of this update at 12% app volume. Typing sounds follow actual keypresses, not programmatic text changes. After that, saved sound choices are respected. Click, typing and volume controls remain in settings; Windows-wide sounds are not changed."},
   {"Auto-character creator","Choose New character in the workbench toolbar, New > Character creation, or Auto character in Project Manager > Project files. Choose Assisted or Advanced. Both open a separate editor, preserving your current entry. Advanced opens the full manual workbench. Assisted writes for you from a brief.\r\n\r\nPick one of 36 templates in Civilians, Outlaws, Agency, Nexus, Military or Arena. Each clones a distinct real character preset, preserving appearance, animations, armor, corpus, skills and references. Search by name or source ID, or filter by category.\r\n\r\nOnly a name is required. With Write my profile and backstory enabled, choose personality and motivation and add any extra details. Assisted automatically writes Description and an embedded Backstory note, shown in Preview. This writing uses built-in rules and the selected template; it does not call an online AI service. Turn it off for manual writing. Set an optional short name, title, faction, level, durability and movement in Basics. Details contains body size, weapon slots and backstory. Extra details are included in the profile and story. A backstory override replaces the generated story exactly. The Backstory note lives in the same JSON. Weapons use loaded IDs; a primary override updates weapon preference when its category is known.\r\n\r\nPreview shows the result. Review character opens the workbench, where Save JSON writes it to disk. Project launches target the characters folder. Source presets stay untouched.\r\n\r\nLevel sets only the Level field. Durability scales health/toughness; movement scales the template speed vector; body size multiplies its scale. Defaults preserve inherited values. These are editable starting points: preview, review and test balance in game."},
   {"Project Manager","Open Projects from the main window or entry editor. New project creates a home folder with characters, weapons, armor, rooms, assets and exports subfolders. Open project loads dossier-project.json; Recent projects reopens previous homes. Name and description are saved with Save project details / Ctrl+S.\r\n\r\nOverview lists folder links. Link folder leaves existing files in place; Set type chooses their entry type. Link a deck adds its folders while preserving the deck. Unlink removes only the link. Import files copies into the selected folder, preserving originals and using numbered names for collisions.\r\n\r\nProject files searches filenames/paths and previews JSON or small text assets. Choose a folder filter to create a new entry there. Edit entry opens typed JSON in its workbench, with embedded Notes, or opens room JSON in Rooms. Each editor saves its own files. Refresh files rescans after external changes. Show in folder locates assets in Explorer.\r\n\r\nProject ideas opens a board saved inside this project as project-ideas.json. Its cards and tasks are separate from the global gallery and other projects. Relative internal links survive moving the whole project home. External links stay absolute: include their files separately when sharing.\r\n\r\nMissing links are reported; unlink and relink to repair them. Manifest overwrites retain .bak. File scans are limited to 5,000 files and skip backups, temporary files and reparse-point subfolders. JSON preview/edit launch limit: 2 MB. Project notes describe the project; character notes still live in their own entry JSON."},
   {"Entry notes","In the entry editor, open Notes > Notes for this entry. Add titled notes for backstory, relationships, design ideas or reminders. Search matches titles and text; Duplicate makes a copy of the selected note. Remove asks before deleting.\r\n\r\nApply to entry (Ctrl+S in the Notes window) puts the notes into the current working entry. Then use Save JSON in the workbench to write them into that same character, weapon, armor or other entry file. There is no separate notes file. Copying the JSON copies the notes too.\r\n\r\nCancel or closing with unapplied changes offers a choice to apply or discard. Workbench Undo/Redo includes applied note changes. Existing notes reload with the entry and unknown metadata is retained. Notes are editor annotations and do not alter character gameplay attributes."},
   {"Game copies on Save","Entry editor > File > Game folder / auto-send selects your Custom Stuff folder and enables automatic copying after Save JSON / Ctrl+S. The editor type determines the destination: characters go into characters, rooms into rooms, ranged weapons into ranged, and other game JSON types into their matching folders. Your local/project copy is kept. Existing game JSON gets a .bak backup. The status bar reports success or a failed game copy; a copy failure does not discard the local save. Unfinished edits, project manifests and idea boards are not copied. A working NEM installation is required for the game to use exported files."},
   {"Room editor","Use Characters for a searchable roster labelled Player, Ally, Enemy, Neutral or Scene Default. Roles use controller and faction values, including matching template defaults; scripts and squads can change them later. Search presets by name or ID, pick a replacement or type a custom ID, and change a displayed name without renaming a scene/spawn ID. Quick role assignment sets both controller and faction. Player spawns may still use their saved career squad.\r\n\r\nUse Dialogue for cutscene lines, area speech, conversations and goodbyes. Search by text, room or speaker, edit text with line breaks and game tags, and select or type a speaker serial for cutscene lines. Ctrl+Enter applies and moves to the next line; switching entries also applies changes. Step indices, actions, sounds and other fields are preserved. Done returns to the room editor: Save writes the file and Undo restores quick edits. Matching templates supply inherited data without copying unedited values into the override.\r\n\r\nStart with Simple view: choose a room file, open a category, select an object and edit its settings. Switches, text fields and readable reference choices preserve the original types. Apply changes updates the working copy; Save / Ctrl+S writes it to disk. Invalid numbers stop the whole batch from applying. Advanced contains the original property-name, type and raw JSON editor for custom fields.\r\n\r\nTemplates open as copies; saving asks for a destination. Use template opens the matching stage template. Make copy detaches the current room from its original file. Add from template offers missing fields or list entries at the selected location, copying real values and IDs.\r\n\r\nFilter to overrides or templates, search filenames, or use Previous file / Next file. Expand all / Collapse all helps navigate categories. Right-click entries to copy their identifier or JSON. Undo/Redo restores edits while keeping your selection and expanded sections where possible. Duplicate and Move up/down are useful for lists; explicit cutscene Index fields are preserved.\r\n\r\nSave keeps an overwritten file as .bak. Switching files or closing prompts for unsaved changes. Check file validates structure while preserving unknown fields and sparse overrides. Rooms folders can also be linked in Decks.\r\n\r\nThese files override existing rooms, not 3D geometry. Preserve stage filenames, room names and object IDs from the templates: invented IDs do not create scene objects. All 146 supplied files passed semantic save/reload checks without changing originals. In-game behavior still needs testing."},
   {"High-resolution displays","Dossier and Theme Editor now use native per-monitor DPI awareness on Windows 10/11 with .NET Framework 4.8. Text and controls are rendered at the screen's current scale instead of enlarging a low-resolution window image. Custom character rows, tabs, dossier summaries and idea cards use DPI-aware measurements.\r\n\r\nWindow sizes are limited to the available screen area. Card exports are rendered afresh at 3,000 pixels wide and 288 DPI. Original portrait images retain their source detail.\r\n\r\nRestart the application after updating, and keep each .exe.config file beside its executable. DPI configuration follows Microsoft's Windows Forms high-DPI guidance: https://learn.microsoft.com/en-us/dotnet/desktop/winforms/high-dpi-support-in-windows-forms?view=netframeworkdesktop-4.8"},
   {"Idea Gallery and to-do lists","Open Idea Gallery from the browser header or entry editor menu. New idea (Ctrl+N) creates a card with a title, notes, tags, priority and its own to-do list. Add, rename or remove tasks, and check off completed items. Save idea applies the edits; Cancel leaves the original card unchanged.\r\n\r\nDrag cards between Ideas, To do, In progress and Done, or right-click a card to move it to a chosen column. Drop above another card to reorder. You can also choose its column while editing. Checklist progress appears on each card; finishing a checklist does not automatically move the card.\r\n\r\nSearch (Ctrl+F) matches titles, notes, tags and task text. Archive retains a card while hiding it from the active board. View archive shows archived ideas, where Restore card returns them to the active board.\r\n\r\nBoard changes save locally to %LOCALAPPDATA%/MPNDossier/ideas.json, with a .bak copy of the previous save. Export board saves a JSON backup wherever you choose. If the primary save is unreadable, the gallery tries the backup. The board is separate from game JSON and deck files."},
   {"Autocomplete and recommendations","Reference and enum fields suggest valid choices below the value box. Search by ID or readable display name. Use Up/Down to select, Tab or Enter to accept, or Escape to dismiss. Clicking a suggestion also applies it.\r\n\r\nA partial or unmatched reference search preserves the previous value. Acceptance writes the ID or enum value, not the display label. Full exact IDs are also accepted directly.\r\n\r\nRecommendations rank recent accepted choices and, for character weapon slots, weapons whose category matches WeaponPreference. They do not perform a full equipment compatibility check. Numeric suggestions come from documented special values in the MadCard Maker reference. Plain text fields remain free text."},
   {"Decks and folders","Open Decks from the browser or editor menu. Enter a name and choose New deck. Select an entry type, such as characters or weapons, before adding a folder. Choose Files for general assets such as images, sounds and notes. A deck can contain several folders of different types.\r\n\r\nSelect a folder to browse its files. Filter by filename, preview JSON, or choose Edit JSON entry. New entry here opens a template whose save dialog targets the linked folder. Entry types must match Dossier's JSON schema.\r\n\r\nRemoving a deck or unlinking a folder changes saved links only; it leaves source files on disk. Deck links are stored in %LOCALAPPDATA%/MPNDossier/decks.json. Deck folders are not automatically mounted into the browser's database or installed into the game. The browser continues loading db/base, db/nem and db/new.\r\n\r\nFiles up to 2 MB can be previewed/edited. Folder scans stop at 5,000 files and skip linked subdirectories. Unknown JSON object fields are preserved on export."},
   {"Getting started","Browse characters on the left. Search by name, ID or title, then choose a tab to view attributes, personality, equipment, weapons or skills.\r\n\r\nOpen Entry editor to create custom JSON entries. The browser is a viewer; editing happens in the separate workbench.\r\n\r\nPress F1 anywhere for this guide."},
   {"Search, favorites and recent characters","Ctrl+F focuses search. Multiple words must all match the character's name, ID or title. The faction filter narrows the list further.\r\n\r\nFavorite saves a bookmark; Ctrl+D toggles it. Choose Favorites to see bookmarks, or Recent to see the last 20 subjects. These are stored with your interface preferences."},
   {"Compare, copy and export","Pin comparison holds the current character's base attributes. Choose another to see how Strength, Endurance, Dexterity and Tactics differ. Press Unpin to clear it. These are base JSON values, before trait effects.\r\n\r\nCopy summary puts text on the clipboard. Export PNG saves a picture of the summary; it does not export a game entry."},
   {"Create and load entries","Entry editor starts with a character template. Use File > New for weapons, armor, animations and other supported types. Load entry chooses an existing entry of the current type from the database.\r\n\r\nSave before creating or loading another entry: switching starts a new document and history. The entry name becomes its JSON filename."},
   {"Edit properties and lists","Select a property on the left. Read its explanation on the right, then type a value below or choose an available reference.\r\n\r\nAdd item adds a list child; Remove item removes the selected child. Fixed lists cannot change length. Toggle changes a boolean. Choose color opens a picker. Expand nested objects to edit their fields.\r\n\r\nEnum choices may include a description of the selected value. The reference documents a different editor version, so unmatched fields are marked explicitly."},
   {"Save JSON and backups","Save JSON (Ctrl+S) opens a save dialog. Save custom entries under db/new/<entry type>/ so Dossier discovers them next launch. A JSON saved elsewhere is not automatically loaded.\r\n\r\nOverwriting creates a .bak copy. A temporary file is written before replacing the destination. Saving does not automatically install a mod into the game. Use the existing transfer tools only with your configured game folder."},
   {"Undo and redo","Ctrl+Z undoes a property or list change; Ctrl+Y restores it. History holds up to 100 snapshots in the current entry. Creating, loading or saving an entry starts a new history.\r\n\r\nSave before switching entries or closing the workbench."},
   {"Glossary","The glossary shows database records and enum definitions. Select a category or entry on the left; its properties and description appear on the right. Type a name and use Find next or Enter to cycle through matches."},
   {"Fonts, themes and sound","The bundled Play font is used by default; no system font installation is required. Open DossierThemeEditor.exe to change colors or choose an installed font. Save & apply, then restart Dossier. Import and export share theme JSON files.\r\n\r\nSound opens optional interface clicks and typing ticks with a volume slider. Effects default to off. Theme and interface settings live under %LOCALAPPDATA%/MPNDossier."},
   {"About this rewrite and the reference","This application is a rewrite of the older Dossier tool. Original product credits and attribution are retained.\r\n\r\nField and enum explanations come from the supplied MadCard Maker/db/Tooltips_Obj.json and Tooltips_Enums.json. Original wording is retained where a matching schema field exists. Different field names have explicit mappings; no matching description is invented.\r\n\r\nMadCard Maker itself and its database are unchanged.\r\n\r\nPlay font: Jonas Hecksher / Playtypes / e-types AS, distributed under the SIL Open Font License 1.1. See UI-Source/Fonts/OFL.txt."}
  };
  foreach(var obj in Objects.Properties()){
   var title="Reference / "+obj.Name;var text=Format(obj.Value);if(text.Length>0)items[title]=text;
   if(obj.Value["Properties"] is JObject props)foreach(var prop in props.Properties())items[title+" / "+prop.Name]=Format(prop.Value);
  }
  foreach(var group in Enums.Properties())if(group.Value is JObject entries)foreach(var entry in entries.Properties())items["Enums / "+group.Name+" / "+entry.Name]=Format(entry.Value);
  return items;
 }
 public static void Open(IWin32Window owner){var form=Application.OpenForms.OfType<DossierHelpForm>().FirstOrDefault();if(form==null){form=new DossierHelpForm();StudioModule.ShowDocument(form,owner);}else{form.WindowState=FormWindowState.Normal;StudioModule.ActivateDocument(form);}}
}
